func TestParsePrice(t *testing.T) {
    tests := []struct {
        name    string
        in      string
        want    int64
        wantErr bool
    }{
        {"целое", "100", 10000, false},
        {"копейки", "99.95", 9995, false},
        {"мусор", "abc", 0, true},
    }
    for _, tt := range tests {
        t.Run(tt.name, func(t *testing.T) {
            t.Parallel()                     // подтесты параллельно
            got, err := ParsePrice(tt.in)
            if (err != nil) != tt.wantErr {
                t.Fatalf("err = %v, wantErr %v", err, tt.wantErr)
            }
            if got != tt.want {
                t.Errorf("got %d, want %d", got, tt.want)
            }
        })
    }
}

func TestCacheExpires(t *testing.T) {
    synctest.Test(t, func(t *testing.T) {
        c := NewCache(time.Minute)
        c.Set("k", "v")
        time.Sleep(61 * time.Second)   // мгновенно: часы виртуальные
        synctest.Wait()
        if _, ok := c.Get("k"); ok {
            t.Fatal("значение не истекло")
        }
    })
}

func FuzzParsePrice(f *testing.F) {
    f.Add("99.95")
    f.Fuzz(func(t *testing.T, s string) {
        p, err := ParsePrice(s)
        if err == nil && p < 0 {
            t.Errorf("отрицательная цена для %q", s)
        }
    })
}
// go test -fuzz=FuzzParsePrice -fuzztime=30s
